(()=>{
  const E=__echoes;
  E.cmd('giveSkill','warding_aura');
  E.cmd('giveSkill','restorative_wave');
  for(const n of ['sharpen','ascend','multiply','bounce','siphon','echo','detonate','quicken']) E.cmd('grantNode',n);
  E.cmd('socket','mending_bolt','sharpen',0);
  E.cmd('socket','mending_bolt','ascend',1);
  E.cmd('socket','warding_aura','bounce',0);
  E.cmd('socket','restorative_wave','multiply',0);
  const r=E.cmd('openSocket');
  const geo={open:r};
  geo.cards=[...document.querySelectorAll('.nd-card')].map((el,i)=>{const b=el.getBoundingClientRect();return {i,text:el.innerText.replace(/\n/g,'|'),x:Math.round(b.x+b.width/2),y:Math.round(b.y+b.height/2)};});
  geo.rows=[...document.querySelectorAll('.nd-row')].map(el=>({name:el.querySelector('.nd-skill-name').textContent,cells:[...el.querySelectorAll('.nd-cell')].map(c=>{const b=c.getBoundingClientRect();return {cls:c.className,x:Math.round(b.x+b.width/2),y:Math.round(b.y+b.height/2)};})}));
  geo.page=(()=>{const b=document.querySelector('.nd-page').getBoundingClientRect();return {x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height)};})();
  geo.bodyScroll=(()=>{const b=document.querySelector('.nd-body');return {sh:b.scrollHeight,ch:b.clientHeight};})();
  return JSON.stringify(geo);
})()
